# ---------- Data helpers ----------
def load_data():
    if not DATA_FILE.exists():
        return []
    try:
        data = json.loads(DATA_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, list) else []
    except (json.JSONDecodeError, OSError):
        return []

def save_data(rows):
    DATA_FILE.write_text(json.dumps(rows, indent=2, ensure_ascii=False), encoding="utf-8")

def new_id():
    return "CVX-" + uuid.uuid4().hex[:8].upper()

def priority_for(category, details):
    text = f"{category} {details}".lower()
    if any(w in text for w in ("fire", "collapse", "electrocution", "life threatening", "emergency")):
        return "Critical"
    if any(w in text for w in ("accident", "dangerous", "sewage", "overflow", "broken pole")):
        return "High"
    if category in ("Public Safety", "Water Supply"):
        return "High"
    if category in ("Roads & Infrastructure", "Electricity"):
        return "Medium"
    return "Low"

def get_case(case_id):
    for case in load_data():
        if case.get("id", "").lower() == case_id.lower():
            return case
    return None

def status_counts(rows):
    return {s: sum(1 for r in rows if r.get("status") == s)
            for s in ("Submitted", "Assigned", "In progress", "Resolved")}

# ---------- Sidebar ----------
rows = load_data()
