# ---------- Overview ----------
if selected == "Overview":
    open_cases = sum(r.get("status") != "Resolved" for r in rows)
    resolved = sum(r.get("status") == "Resolved" for r in rows)
    st.markdown("""
    <div class="hero">
      <div class="eyebrow">CIVIX AI 2.0 &nbsp; / &nbsp; CIVIC RESPONSE PLATFORM</div>
      <h1>Better cities begin<br>with being heard.</h1>
      <p>One clear path from a resident’s report to a team’s response.
      Capture the issue, follow its progress, and make every update visible.</p>
      <span class="pill">01 &nbsp; REPORT</span>
      <span class="pill">02 &nbsp; ROUTE</span>
      <span class="pill">03 &nbsp; RESOLVE</span>
    </div>
    """, unsafe_allow_html=True)

    k1, k2, k3, k4 = st.columns(4)
    metrics = [
        ("ALL REPORTS", len(rows), "Every submitted case"),
        ("NEEDS ACTION", open_cases, "Not yet resolved"),
        ("RESOLVED", resolved, "Marked complete"),
        ("RESOLUTION RATE", f"{round(resolved / len(rows) * 100) if rows else 0}%", "Based on demo records"),
    ]
    for col, (label, value, hint) in zip((k1, k2, k3, k4), metrics):
        with col:
            st.markdown(f'<div class="card"><div class="label">{label}</div><div class="value">{value}</div><div class="hint">{hint}</div></div>', unsafe_allow_html=True)

    st.write("")
    left, right = st.columns([1.15, 1])
    with left:
        st.markdown('<div class="section-kicker">CITIZEN ACCESS</div>', unsafe_allow_html=True)
        st.subheader("Make a report")
        st.write("Describe the issue, add its location, and attach a photo if you have one.")
        if st.button("＋  Submit a civic issue", type="primary", use_container_width=True):
            st.session_state["page_choice"] = "Report an issue"
            st.rerun()
    with right:
        st.markdown('<div class="section-kicker">OPERATIONS</div>', unsafe_allow_html=True)
        st.subheader("Response desk")
        st.write("Review reports, filter the queue, and update case status.")
        if st.button("Open response desk  →", use_container_width=True):
            st.session_state["page_choice"] = "Response desk"
            st.rerun()

    st.markdown("---")
    st.subheader("Latest reports")
    if rows:
        recent = pd.DataFrame(rows[:6])
        show = [c for c in ["id", "created", "category", "area", "priority", "status"] if c in recent.columns]
        st.dataframe(recent[show], use_container_width=True, hide_index=True)
    else:
        st.info("No reports yet. Submit a sample issue to populate the overview.")

# ---------- Report ----------
elif selected == "Report an issue":
    st.markdown('<div class="section-kicker">RESIDENT INTAKE</div>', unsafe_allow_html=True)
    st.title("Report a civic issue")
    st.write("Give the response team enough detail to locate and understand the problem.")
    with st.form("new_report", clear_on_submit=True):
        a, b = st.columns(2)
        with a:
            reporter = st.text_input("Your name *")
            category = st.selectbox("Issue type *", ["Roads & Infrastructure", "Water Supply", "Sanitation", "Electricity", "Public Safety", "Other"])
            area = st.text_input("Area / locality *", placeholder="e.g. Avadi")
        with b:
            contact = st.text_input("Contact number (optional)")
            landmark = st.text_input("Nearby landmark")

            address = st.text_input("Street / address (optional)")
        st.markdown("#### Pin the issue location")
        st.caption("Allow location access in your browser using the target icon on the map, or click the map to place a pin.")
        if "report_lat" not in st.session_state:
            st.session_state["report_lat"] = None
        if "report_lon" not in st.session_state:
            st.session_state["report_lon"] = None

        map_center = (
            [st.session_state["report_lat"], st.session_state["report_lon"]]
            if st.session_state["report_lat"] is not None and st.session_state["report_lon"] is not None
            else [13.1143, 80.1098]  # Avadi-area default; user can move/zoom the map
        )
        issue_map = folium.Map(location=map_center, zoom_start=15, control_scale=True)
        LocateControl(
            auto_start=False,
            strings={"title": "Use my current location", "popup": "Current browser location"}
        ).add_to(issue_map)
        if st.session_state["report_lat"] is not None and st.session_state["report_lon"] is not None:
            folium.Marker(
                map_center,
                tooltip="Selected issue location",
                popup=f"Selected coordinates: {map_center[0]:.6f}, {map_center[1]:.6f}",
                icon=folium.Icon(color="green", icon="map-marker")
            ).add_to(issue_map)

        map_result = st_folium(
            issue_map,
            height=360,
            use_container_width=True,
            returned_objects=["last_clicked"],
            key="issue_location_map"
        )
        if map_result and map_result.get("last_clicked"):
            clicked = map_result["last_clicked"]
            st.session_state["report_lat"] = float(clicked["lat"])
            st.session_state["report_lon"] = float(clicked["lng"])
        if st.session_state["report_lat"] is not None and st.session_state["report_lon"] is not None:
            st.success(
                f"Selected coordinates: {st.session_state['report_lat']:.6f}, "
                f"{st.session_state['report_lon']:.6f}"
            )
        details = st.text_area("What is happening? *", height=150, placeholder="Describe the issue, when it started, and any immediate risk.")
        photo = st.file_uploader("Photo evidence (optional)", type=["png", "jpg", "jpeg", "webp"])
        submitted = st.form_submit_button("Submit report", type="primary", use_container_width=True)

    if submitted:
        if not reporter.strip() or not area.strip() or not details.strip():
            st.error("Please complete your name, area, and issue description.")
        else:
            case_id = new_id()
            photo_path = None
            if photo:
                suffix = Path(photo.name).suffix.lower()
                if suffix not in (".png", ".jpg", ".jpeg", ".webp"):
                    suffix = ".jpg"
                photo_path = UPLOAD_DIR / f"{case_id}{suffix}"
                photo_path.write_bytes(photo.getvalue())
                photo_path = str(photo_path)
            priority = priority_for(category, details)
            item = {
                "id": case_id,
                "created": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "reporter": reporter.strip(),
                "contact": contact.strip(),
                "category": category,
                "area": area.strip(),
                "landmark": landmark.strip(),
                "address": address.strip(),
                "latitude": st.session_state.get("report_lat"),
                "longitude": st.session_state.get("report_lon"),
                "details": details.strip(),
                "priority": priority,
                "status": "Submitted",
                "photo": photo_path,
                "updates": [{"time": datetime.now().strftime("%Y-%m-%d %H:%M"), "status": "Submitted", "note": "Report received"}],
            }
            rows = load_data()
            rows.insert(0, item)
            save_data(rows)
            st.success("Report received. Keep this tracking ID:")
            st.code(case_id)
            st.caption(f"Suggested priority: {priority}. This is a transparent keyword-rule demo, not an AI model.")

# ---------- Track ----------
elif selected == "Track a report":
    st.markdown('<div class="section-kicker">PUBLIC STATUS LOOKUP</div>', unsafe_allow_html=True)
    st.title("Track a report")
    entered = st.text_input("Tracking ID", placeholder="CVX-XXXXXXXX")
    if st.button("Find report", type="primary"):
        st.session_state["tracking_result"] = get_case(entered.strip()) if entered.strip() else None
        st.session_state["tracking_searched"] = True

    if st.session_state.get("tracking_searched"):
        case = st.session_state.get("tracking_result")
        if not case:
            st.error("No report found. Check the tracking ID and try again.")
        else:
            st.markdown(f'<div class="card"><div class="label">TRACKING ID</div><div class="value">{case["id"]}</div><div class="hint">{case["area"]} · {case["category"]}</div></div>', unsafe_allow_html=True)
            x, y, z = st.columns(3)
            x.metric("Current status", case["status"])
            y.metric("Priority", case["priority"])
            z.metric("Reported", case["created"])
            st.subheader("Activity timeline")
            for event in reversed(case.get("updates", [])):
                st.markdown(f"**{event['status']}** · {event['time']}  \n{event.get('note', '')}")
                st.markdown("---")
            if case.get("photo") and Path(case["photo"]).exists():
                st.image(case["photo"], caption="Submitted evidence", width=500)

# ---------- Response desk ----------
elif selected == "Response desk":
    st.markdown('<div class="section-kicker">STAFF WORKSPACE</div>', unsafe_allow_html=True)
    st.title("Response desk")
    st.write("Triage the queue and record progress so the report timeline stays transparent.")
    rows = load_data()
    if not rows:
        st.info("No reports are waiting in the queue.")
    else:
        f1, f2 = st.columns(2)
        status_filter = f1.selectbox("Status", ["All", "Submitted", "Assigned", "In progress", "Resolved"])
        dept_filter = f2.selectbox("Issue type", ["All"] + sorted(set(r.get("category", "Other") for r in rows)))
        filtered = rows
        if status_filter != "All":
            filtered = [r for r in filtered if r.get("status") == status_filter]
        if dept_filter != "All":
            filtered = [r for r in filtered if r.get("category") == dept_filter]
        st.caption(f"{len(filtered)} case(s) in this view")
        for item in filtered:
            with st.expander(f"{item['id']}  ·  {item['priority']}  ·  {item['category']}  ·  {item['area']}"):
                st.write(item["details"])
                st.caption(f"Submitted by {item.get('reporter', 'Resident')} · {item['created']}")
                with st.form(f"update_{item['id']}"):
                    new_status = st.selectbox("Update status", ["Submitted", "Assigned", "In progress", "Resolved", "Reopened"],
                                               index=["Submitted", "Assigned", "In progress", "Resolved", "Reopened"].index(item["status"])
                                               if item["status"] in ["Submitted", "Assigned", "In progress", "Resolved", "Reopened"] else 0)
                    note = st.text_input("Public update note", placeholder="e.g. Team assigned; inspection scheduled")
                    save = st.form_submit_button("Save case update", type="primary")
                if save:
                    current = load_data()
                    for record in current:
                        if record["id"] == item["id"]:
                            record["status"] = new_status
                            record.setdefault("updates", []).append({
                                "time": datetime.now().strftime("%Y-%m-%d %H:%M"),
                                "status": new_status,
                                "note": note.strip() or "Status updated",
                            })
                            break
                    save_data(current)
                    st.success("Update saved.")
                    st.rerun()

# ---------- City signals ----------
elif selected == "City signals":
    st.markdown('<div class="section-kicker">PATTERN SNAPSHOT</div>', unsafe_allow_html=True)
    st.title("City signals")
    st.write("Explore the issues reported in this prototype dataset.")
    rows = load_data()
    if not rows:
        st.info("Submit reports to build the city signal view.")
    else:
        df = pd.DataFrame(rows)
        c1, c2 = st.columns(2)
        with c1:
            st.subheader("Reports by issue type")
            st.bar_chart(df["category"].value_counts())
        with c2:
            st.subheader("Reports by status")
            st.bar_chart(df["status"].value_counts())
        st.subheader("Most-reported areas")
        st.bar_chart(df["area"].value_counts().head(10))
        st.caption("This is a view of local prototype data, not official city-wide statistics.")
